package id.unnes.bemfhunnes.article;
import id.unnes.bemfhunnes.auth.AuthService; import jakarta.servlet.http.HttpServletRequest; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; import java.util.*;
@RestController @RequestMapping("/api") public class ArticleController {private final ArticleService articles;private final AuthService auth;public ArticleController(ArticleService a,AuthService u){articles=a;auth=u;} @GetMapping("/health") public Map<String,Boolean> health(){return Map.of("ok",true);} @GetMapping("/articles") public Map<String,Object> list(@RequestParam(required=false)String section,@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="6")int pageSize){return articles.list(section,null,Math.max(page,1),Math.min(Math.max(pageSize,1),50),false);} @GetMapping("/articles/{slug}") public ResponseEntity<?> get(@PathVariable String slug){var a=articles.get(slug);return a==null?ResponseEntity.notFound().build():ResponseEntity.ok(Map.of("article",a));} @GetMapping("/admin/insights") public Map<String,Object> insights(HttpServletRequest r){auth.requireRole(r,"admin","superadmin");return Map.of("counts",articles.insights());} @GetMapping("/admin/articles") public Map<String,Object> adminList(HttpServletRequest r,@RequestParam(required=false)String section,@RequestParam(required=false)String status,@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="6")int pageSize){auth.requireRole(r,"admin","superadmin");return articles.list(section,status,Math.max(page,1),Math.min(Math.max(pageSize,1),50),true);} @GetMapping("/admin/articles/{id}") public ResponseEntity<?> adminGet(HttpServletRequest r,@PathVariable long id){auth.requireRole(r,"admin","superadmin");var a=articles.adminGet(id);return a==null?ResponseEntity.notFound().build():ResponseEntity.ok(Map.of("article",a));} @PostMapping(value="/admin/articles",consumes=MediaType.MULTIPART_FORM_DATA_VALUE) public ResponseEntity<?> create(HttpServletRequest r,@RequestParam String section,@RequestParam String title,@RequestParam String description,@RequestParam String body,@RequestParam(defaultValue="pending")String status,@RequestPart(required=false)MultipartFile image)throws Exception{var u=auth.user(r);return ResponseEntity.status(HttpStatus.CREATED).body(Map.of("article",articles.create(section,title,description,body,status,image,((Number)u.get("sub")).longValue())));} @PatchMapping(value="/admin/articles/{id}",consumes=MediaType.MULTIPART_FORM_DATA_VALUE) public Map<String,Object> update(HttpServletRequest r,@PathVariable long id,@RequestParam String section,@RequestParam String title,@RequestParam String description,@RequestParam String body,@RequestParam(defaultValue="pending")String status,@RequestPart(required=false)MultipartFile image)throws Exception{auth.requireRole(r,"admin","superadmin");return Map.of("article",articles.update(id,section,title,description,body,status,image));} @PatchMapping("/admin/articles/{id}/status") public Map<String,Object> status(HttpServletRequest r,@PathVariable long id,@RequestBody Map<String,String> body)throws Exception{auth.requireRole(r,"admin","superadmin");return Map.of("article",articles.status(id,body.get("status")));}}
